begin;create extension if not exists pgtap with schema extensions;select plan(27);
-- 9901 normal; 9902 swapped; 9903 partial; 9904 mismatch; 9905 conflict; 9906 result unavailable.
update public.dota_matches set radiant_win=null where match_id=9906;
select is(public.reconcile_external_dota_match('91000000-0000-4000-8000-000000000301'),'matched','complete ten-player match');select is((select reconciliation_state::text from public.match_external_links where id='91000000-0000-4000-8000-000000000301'),'matched','matched persisted');select is((select radiant_team_id from public.match_external_links where id='91000000-0000-4000-8000-000000000301'),'91000000-0000-4000-8000-0000000000a1'::uuid,'normal radiant derived');select is((select result_agrees from public.match_external_links where id='91000000-0000-4000-8000-000000000301'),true,'external result agrees');
select is(public.reconcile_external_dota_match('91000000-0000-4000-8000-000000000302'),'matched','swapped match reconciles');select is((select radiant_team_id from public.match_external_links where id='91000000-0000-4000-8000-000000000302'),'91000000-0000-4000-8000-0000000000b1'::uuid,'Team B derived Radiant');select is((select dire_team_id from public.match_external_links where id='91000000-0000-4000-8000-000000000302'),'91000000-0000-4000-8000-0000000000a1'::uuid,'Team A derived Dire');select is((select result_agrees from public.match_external_links where id='91000000-0000-4000-8000-000000000302'),true,'swapped winner agrees');select is(public.reconcile_external_dota_match('91000000-0000-4000-8000-000000000303'),'partial','nine known is partial');
update public.match_external_links set dota_match_id=9905 where id='91000000-0000-4000-8000-000000000304';update public.match_games set winner_team_id='91000000-0000-4000-8000-0000000000b1'where id='91000000-0000-4000-8000-000000000101';select is(public.reconcile_external_dota_match('91000000-0000-4000-8000-000000000304'),'result_conflict','result conflict detected');select is((select winner_team_id from public.match_games where id='91000000-0000-4000-8000-000000000101'),'91000000-0000-4000-8000-0000000000b1'::uuid,'conflict preserves canonical result');
update public.match_external_links set dota_match_id=9906 where id='91000000-0000-4000-8000-000000000304';select is(public.reconcile_external_dota_match('91000000-0000-4000-8000-000000000304'),'matched','unavailable winner leaves participants matched');select is((select external_winner_team_id from public.match_external_links where id='91000000-0000-4000-8000-000000000304'),null::uuid,'unavailable winner remains null');
select throws_ok($$insert into public.dota_match_players(match_id,slot,account_id,is_radiant)values(9901,10,1001,true)$$,'23505',null,'duplicate external identity rejected');select throws_ok($$insert into public.match_external_links(match_game_id,dota_match_id,linked_by)values('91000000-0000-4000-8000-000000000103',9901,'00000000-0000-4000-8000-000000000001')$$,'23505',null,'external match cannot link twice');
set local role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000006',true);select throws_ok($$select public.relink_external_dota_match('91000000-0000-4000-8000-000000000304',9910,'captain correction')$$,'P0001','UNAUTHORIZED_REFEREE','captain cannot relink');select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);select lives_ok($$select public.relink_external_dota_match('91000000-0000-4000-8000-000000000304',9910,'verified wrong match')$$,'organizer relinks');select is((select old_dota_match_id from public.match_external_link_history where match_external_link_id='91000000-0000-4000-8000-000000000304'),9906::bigint,'old link retained');select is((select count(*) from public.audit_events where event_type='EXTERNAL_MATCH_RELINKED'),1::bigint,'relink audited');
reset role;select ok(exists(select 1 from public.public_player_dota_stats where public_slug is not null),'career Dota aggregate available');select ok(exists(select 1 from public.public_tournament_dota_stats where tournament_slug='phase09b'),'tournament completeness aggregate available');select public.record_provider_state('opendota','open',3,now()+interval'30 seconds','failure');select is((select circuit_state from public.external_provider_health where provider='opendota'),'open','provider circuit opens automatically');select is((select recent_error_count from public.external_provider_health where provider='opendota'),1,'provider failure counter updates');select public.record_provider_state('opendota','closed',0,'epoch','recovered');select is((select circuit_state from public.external_provider_health where provider='opendota'),'closed','provider recovery closes circuit');select is((select count(*) from public.audit_events where event_type in('PROVIDER_DEGRADED','PROVIDER_RECOVERED')),2::bigint,'health transitions audited without routine spam');select *from finish();rollback;
